commands.command:
$captureDir = Join-Path (Get-Location) 'captures'
[System.IO.Directory]::CreateDirectory($captureDir) | Out-Null
$stdoutPath = Join-Path $captureDir '001-read-skill.stdout.txt'
$stderrPath = Join-Path $captureDir '001-read-skill.stderr.txt'
if ((Test-Path -LiteralPath $stdoutPath) -or (Test-Path -LiteralPath $stderrPath)) { throw 'Capture path already exists.' }
[System.IO.File]::WriteAllText($stderrPath, '')
try {
  Get-Content -Raw -LiteralPath 'skills\researching-characters\SKILL.md' -ErrorAction Stop | Tee-Object -FilePath $stdoutPath
  exit 0
} catch {
  $_ | Out-String | Tee-Object -FilePath $stderrPath | Write-Error
  exit 1
}

$captureDir = Join-Path (Get-Location) 'captures'
$stdoutPath = Join-Path $captureDir '003-read-research-contract.stdout.txt'
$stderrPath = Join-Path $captureDir '003-read-research-contract.stderr.txt'
if ((Test-Path -LiteralPath $stdoutPath) -or (Test-Path -LiteralPath $stderrPath)) { throw 'Capture path already exists.' }
[System.IO.File]::WriteAllText($stderrPath, '')
try {
  Get-Content -Raw -LiteralPath 'skills\researching-characters\references\research-contract.md' -ErrorAction Stop | Tee-Object -FilePath $stdoutPath
  exit 0
} catch {
  $message = $_ | Out-String
  [System.IO.File]::WriteAllText($stderrPath, $message)
  Write-Error $message
  exit 1
}

$captureDir = Join-Path (Get-Location) 'captures'
$stdoutPath = Join-Path $captureDir '004-verify-final-and-captures.stdout.txt'
$stderrPath = Join-Path $captureDir '004-verify-final-and-captures.stderr.txt'
if ((Test-Path -LiteralPath $stdoutPath) -or (Test-Path -LiteralPath $stderrPath)) { throw 'Capture path already exists.' }
[System.IO.File]::WriteAllText($stderrPath, '')
try {
  $result = [ordered]@{
    final_md = Get-Content -Raw -LiteralPath 'final.md' -ErrorAction Stop
    capture_files = @(Get-ChildItem -LiteralPath 'captures' -File -ErrorAction Stop | Sort-Object Name | Select-Object -ExpandProperty Name)
  } | ConvertTo-Json -Depth 3
  $result | Tee-Object -FilePath $stdoutPath
  exit 0
} catch {
  $message = $_ | Out-String
  [System.IO.File]::WriteAllText($stderrPath, $message)
  Write-Error $message
  exit 1
}

$captureDir = Join-Path (Get-Location) 'captures'
$stdoutPath = Join-Path $captureDir '005-validate-agent-report.stdout.txt'
$stderrPath = Join-Path $captureDir '005-validate-agent-report.stderr.txt'
if ((Test-Path -LiteralPath $stdoutPath) -or (Test-Path -LiteralPath $stderrPath)) { throw 'Capture path already exists.' }
[System.IO.File]::WriteAllText($stderrPath, '')
try {
  $report = Get-Content -Raw -LiteralPath 'agent-report.json' -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
  [ordered]@{
    valid_json = $true
    schema_version = $report.schema_version
    case_id = $report.case_id
    variant = $report.variant
    final_file = $report.final_file
    final_file_exists = Test-Path -LiteralPath $report.final_file
  } | ConvertTo-Json | Tee-Object -FilePath $stdoutPath
  exit 0
} catch {
  $message = $_ | Out-String
  [System.IO.File]::WriteAllText($stderrPath, $message)
  Write-Error $message
  exit 1
}
